-- Construction / real-estate companies, Hyderabad (part 4) — Google Maps export across
-- 12 outer-ring area searches (Bowrampet, Bandlaguda Jagir, Pocharam, Ghatkesar,
-- Shamirpet, Adibatla, Badangpet, Beeramguda and more), captured 28 Sep 2026.
-- Rows #4720-5515 of the cumulative export; #1-4719 loaded by the earlier files.
-- 780 businesses after removing 16 in-file duplicates
-- (the same company returned by several area searches, matched on phone).
--
-- Loads through a staging table so it also skips accounts ALREADY in
-- companies — matched on name or on the last 10 digits of the phone — which
-- is how it avoids re-adding the businesses the infra import already created.
-- Idempotent: re-running inserts nothing new.

begin;

create temporary table _stage_constr4 (
  id text,
  name text,
  industry text,
  location text,
  open_positions integer,
  description text,
  website text,
  logo text,
  health text,
  margin_pct double precision,
  terms text,
  owner_id text,
  is_client boolean,
  contacts json,
  phone text,
  address text,
  pincode text,
  rating double precision,
  reviews_count integer,
  maps_url text,
  latitude double precision,
  longitude double precision,
  source text,
  hours json,
  notes text,
  tags json
) on commit drop;

;

select s.id, s.name, s.industry, s.location, s.open_positions, s.description, s.website, s.logo, s.health, s.margin_pct, s.terms, s.owner_id, s.is_client, s.contacts, s.phone, s.address, s.pincode, s.rating, s.reviews_count, s.maps_url, s.latitude, s.longitude, s.source, s.hours, s.notes, s.tags
from _stage_constr4 s
where not exists (
  select 1 from public.companies c
  where lower(c.name) = lower(s.name)
)
and not exists (
  select 1 from public.companies c
  where c.phone is not null and s.phone is not null
    and length(regexp_replace(c.phone, '\D', '', 'g')) >= 10
    and right(regexp_replace(c.phone, '\D', '', 'g'), 10)
      = right(regexp_replace(s.phone, '\D', '', 'g'), 10)
)
on conflict (id) do nothing;

commit;
